-- Gestão do trabalho (comentários e checklists por registro) e tráfego pago (snapshots somente leitura da Meta).
CREATE TABLE IF NOT EXISTS record_comments(id BIGINT AUTO_INCREMENT PRIMARY KEY,modulo VARCHAR(64) NOT NULL,registro VARCHAR(64) NOT NULL,autor VARCHAR(120) NOT NULL,autor_tipo VARCHAR(10) NOT NULL DEFAULT 'int',quando VARCHAR(40) NOT NULL,texto VARCHAR(2000) NOT NULL,interno TINYINT NOT NULL DEFAULT 1,KEY idx_comments_registro (modulo,registro,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS record_checklist(id BIGINT AUTO_INCREMENT PRIMARY KEY,modulo VARCHAR(64) NOT NULL,registro VARCHAR(64) NOT NULL,texto VARCHAR(300) NOT NULL,feito TINYINT NOT NULL DEFAULT 0,ordem INT NOT NULL DEFAULT 0,atualizado_em VARCHAR(40) NOT NULL,KEY idx_checklist_registro (modulo,registro,ordem)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ads_snapshots(id BIGINT AUTO_INCREMENT PRIMARY KEY,conta VARCHAR(64) NOT NULL,campanha_id VARCHAR(64) NOT NULL,campanha VARCHAR(200) NOT NULL,periodo VARCHAR(10) NOT NULL,gasto DECIMAL(14,2) NOT NULL DEFAULT 0,impressoes BIGINT NOT NULL DEFAULT 0,alcance BIGINT NOT NULL DEFAULT 0,cliques BIGINT NOT NULL DEFAULT 0,resultados BIGINT NOT NULL DEFAULT 0,moeda VARCHAR(8) NOT NULL DEFAULT '',status VARCHAR(30) NOT NULL DEFAULT '',objetivo VARCHAR(60) NOT NULL DEFAULT '',orcamento_diario DECIMAL(14,2) NOT NULL DEFAULT 0,atualizado_em VARCHAR(40) NOT NULL,UNIQUE KEY uq_ads_snapshot (conta,campanha_id,periodo),KEY idx_ads_periodo (periodo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
